        scale_l7 = max(0.85, min(1.15, 0.85 + (score - 50) / 100))
        
        # Volatility Sizing Penalty (R10-8)
        atr_val = atr_pcts.get(t, 2.0)
        vol_mult = 0.7 if atr_val >= atr_threshold else 1.0
        
        weight *= scale_l7 * vol_mult
        
